package com.fadcam.ui;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;
import android.app.Application;
import android.content.*;
import android.net.Uri;
import android.os.Handler;
import android.os.Looper;
import androidx.media3.common.Player;
import androidx.media3.ui.PlayerView;
import androidx.media3.exoplayer.ExoPlayer;
import com.fadcam.*;
import com.fadcam.playback.PlayerHolder;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.Config;
import org.robolectric.util.ReflectionHelpers;
@RunWith(RobolectricTestRunner.class)
@Config(sdk=35,application=Application.class,shadows=GalleryPreviewLifecycleTest.FrameworkPause.class)
public class GalleryPlayerOwnershipTest {
 @Before public void clean(){ReflectionHelpers.setStaticField(SharedPreferencesManager.class,"instance",null);RuntimeEnvironment.getApplication().getSharedPreferences(Constants.PREFS_NAME,Context.MODE_PRIVATE).edit().clear().commit();ReflectionHelpers.setStaticField(VideoPlayerActivity.class,"activePlayerViewOwner",new java.lang.ref.WeakReference<VideoPlayerActivity>(null));}
 private VideoPlayerActivity owner(ExoPlayer p){VideoPlayerActivity a=Robolectric.buildActivity(VideoPlayerActivity.class).get();a.setTheme(R.style.Base_Theme_FadCam);a.setIntent(VideoPlayerActivity.createGalleryIntent(a,Uri.parse("content://qa/current")));ReflectionHelpers.setField(a,"galleryPreview",true);ReflectionHelpers.setField(a,"player",p);PlayerView view=mock(PlayerView.class);when(view.getPlayer()).thenReturn(p);ReflectionHelpers.setField(a,"playerView",view);ReflectionHelpers.callInstanceMethod(a,"attachSharedPlayerView",ReflectionHelpers.ClassParameter.from(ExoPlayer.class,p));return a;}
 @Test public void pauseDetachesBothOwnedListenersAndLateDestroyCannotPauseNewOwner(){ExoPlayer p=mock(ExoPlayer.class);VideoPlayerActivity old=owner(p);Player.Listener main=mock(Player.Listener.class),wave=mock(Player.Listener.class);ReflectionHelpers.setField(old,"playbackUiListener",main);ReflectionHelpers.setField(old,"waveformPlayerListener",wave);ReflectionHelpers.callInstanceMethod(old,"attachPlayerListeners");ReflectionHelpers.callInstanceMethod(old,"attachPlayerListeners");verify(p,times(1)).addListener(main);verify(p,times(1)).addListener(wave);ReflectionHelpers.callInstanceMethod(old,"onPause");verify(p).removeListener(main);verify(p).removeListener(wave);verify(p,times(1)).pause();VideoPlayerActivity next=owner(p);ReflectionHelpers.callInstanceMethod(old,"onDestroy");verify(p,times(1)).pause();verify(p,never()).seekTo(anyLong());assertNull(Shadows.shadowOf(RuntimeEnvironment.getApplication()).getNextStartedService());assertTrue(ReflectionHelpers.callInstanceMethod(next,"ownsSharedPlayerView"));}
 @Test public void stalePauseCannotStopOrResetSharedPlayerOwnedByAnotherViewer(){ExoPlayer p=mock(ExoPlayer.class);VideoPlayerActivity old=owner(p);VideoPlayerActivity next=owner(p);ReflectionHelpers.callInstanceMethod(old,"onPause");verify(p,never()).pause();verify(p,never()).seekTo(anyLong());assertNull(Shadows.shadowOf(RuntimeEnvironment.getApplication()).getNextStartedService());assertTrue(ReflectionHelpers.callInstanceMethod(next,"ownsSharedPlayerView"));ReflectionHelpers.callInstanceMethod(old,"onDestroy");verify(p,never()).pause();}
 @Test public void waveformLoopStopsAndCanResumeWithoutDuplicateCallbacks(){VideoPlayerActivity a=owner(mock(ExoPlayer.class));ReflectionHelpers.callInstanceMethod(a,"setupWaveformUpdates");Handler h=ReflectionHelpers.getField(a,"waveformHandler");Runnable task=ReflectionHelpers.getField(a,"waveformUpdateRunnable");assertTrue(h.hasCallbacks(task));ReflectionHelpers.callInstanceMethod(a,"onPause");assertFalse(h.hasCallbacks(task));task.run();assertFalse("In-flight stopped runnable must not repost",h.hasCallbacks(task));ReflectionHelpers.callInstanceMethod(a,"startWaveformUpdates");ReflectionHelpers.callInstanceMethod(a,"startWaveformUpdates");assertTrue(h.hasCallbacks(task));ReflectionHelpers.callInstanceMethod(a,"onDestroy");assertFalse(h.hasCallbacks(task));task.run();assertFalse(h.hasCallbacks(task));}
 @Test public void listenerReattachRemovesOldPlayerAndDoesNotDuplicateNewPlayer(){ExoPlayer first=mock(ExoPlayer.class),second=mock(ExoPlayer.class);VideoPlayerActivity a=owner(first);Player.Listener main=mock(Player.Listener.class),wave=mock(Player.Listener.class);ReflectionHelpers.setField(a,"playbackUiListener",main);ReflectionHelpers.setField(a,"waveformPlayerListener",wave);ReflectionHelpers.callInstanceMethod(a,"attachPlayerListeners");ReflectionHelpers.setField(a,"player",second);ReflectionHelpers.callInstanceMethod(a,"attachPlayerListeners");ReflectionHelpers.callInstanceMethod(a,"attachPlayerListeners");verify(first).removeListener(main);verify(first).removeListener(wave);verify(second,times(1)).addListener(main);verify(second,times(1)).addListener(wave);ReflectionHelpers.callInstanceMethod(a,"detachPlayerListeners");verify(second).removeListener(main);verify(second).removeListener(wave);}
 @Test public void readyRecoveryClearsCurrentMediaOnlyAndStaleViewerCannotSeek(){ExoPlayer p=mock(ExoPlayer.class);when(p.getDuration()).thenReturn(1000L);when(p.getCurrentPosition()).thenReturn(2000L);VideoPlayerActivity a=owner(p);Uri current=Uri.parse("content://qa/current"),initial=Uri.parse("content://qa/initial");a.setIntent(VideoPlayerActivity.createGalleryIntent(a,initial));ReflectionHelpers.setField(a,"currentVideoUri",current);SharedPreferencesManager settings=SharedPreferencesManager.getInstance(a);settings.setSavedPlaybackPositionMs(initial.toString(),300);settings.setSavedPlaybackPositionMs(current.toString(),800);ReflectionHelpers.setField(a,"spm",settings);PlayerHolder holder=PlayerHolder.getInstance();ReflectionHelpers.setField(holder,"currentUri",current);ReflectionHelpers.callInstanceMethod(a,"validateCurrentResumePosition");verify(p).seekTo(0);assertEquals(0,settings.getSavedPlaybackPositionMs(current.toString()));assertEquals(300,settings.getSavedPlaybackPositionMs(initial.toString()));clearInvocations(p);owner(p);ReflectionHelpers.callInstanceMethod(a,"validateCurrentResumePosition");verify(p,never()).seekTo(anyLong());}
}
